#include <iostream>
#include <sstream>
#include <string>
#include <cstring>
#include <iomanip>

struct ClientData {
    unsigned int acctNum{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

int main() {
    // Simulate binary random-access file using in-memory stringstream
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    // Pre-allocate 5 blank records
    ClientData blank{};
    for (int i = 0; i < 5; ++i) {
        stream.write(reinterpret_cast<const char*>(&blank), sizeof(ClientData));
    }

    // Input loop: user enters account number, lastname, firstname, balance
    unsigned int acct = 0;
    while (std::cin >> acct && acct != 0) {
        ClientData client{};
        client.acctNum = acct;
        std::string lName, fName;
        double bal = 0.0;
        std::cin >> lName >> fName >> bal;

        std::strncpy(client.lastName, lName.c_str(), sizeof(client.lastName) - 1);
        std::strncpy(client.firstName, fName.c_str(), sizeof(client.firstName) - 1);
        client.balance = bal;

        // Calculate offset and seekp
        std::streampos offset = static_cast<std::streamoff>((client.acctNum - 1) * sizeof(ClientData));
        stream.seekp(offset);
        stream.write(reinterpret_cast<const char*>(&client), sizeof(ClientData));
    }

    // Verify random write by inspecting account 3
    ClientData verify{};
    stream.seekg(static_cast<std::streamoff>(2 * sizeof(ClientData)));
    stream.read(reinterpret_cast<char*>(&verify), sizeof(ClientData));

    std::cout << "Account " << verify.acctNum << ": "
              << verify.lastName << " " << verify.firstName
              << " Balance: " << std::fixed << std::setprecision(2) << verify.balance << "\n";
    return 0;
}

#include <iostream>
#include <sstream>
#include <iomanip>

struct ClientData {
    unsigned int acctNum{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

int main() {
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    // Populate simulated file with 3 records (index 0 blank, index 1 active, index 2 active)
    ClientData recs[3] = {};
    recs[1].acctNum = 29;
    std::char_traits<char>::copy(recs[1].lastName, "Brown", 6);
    std::char_traits<char>::copy(recs[1].firstName, "Nancy", 6);
    recs[1].balance = -24.54;

    recs[2].acctNum = 37;
    std::char_traits<char>::copy(recs[2].lastName, "Barker", 7);
    std::char_traits<char>::copy(recs[2].firstName, "Doug", 5);
    recs[2].balance = 0.00;

    stream.write(reinterpret_cast<const char*>(recs), sizeof(recs));

    // Rewind read pointer to beginning
    stream.seekg(0, std::ios::beg);

    // Print formatted header
    std::cout << std::left << std::setw(6) << "Acct"
              << std::setw(16) << "Last Name"
              << std::setw(11) << "First Name"
              << std::right << std::setw(10) << "Balance" << "\n";

    // Read all records sequentially
    ClientData client{};
    while (stream.read(reinterpret_cast<char*>(&client), sizeof(ClientData))) {
        if (client.acctNum != 0) {
            std::cout << std::left << std::setw(6) << client.acctNum
                      << std::setw(16) << client.lastName
                      << std::setw(11) << client.firstName
                      << std::right << std::setw(10) << std::fixed << std::setprecision(2)
                      << client.balance << "\n";
        }
    }

    return 0;
}
